import type { OpenSettings } from '../automation/types';
import type { FigmaMode } from './utils';
/**
 * The user-facing `figmaOptions` open config. Precedence is per field, not per object: a field set here
 * wins, one left unset falls back to that field's environment variable where it has one; `README.md`
 * holds the per-field mapping.
 *
 * `APPLITOOLS_FIGMA_SKIP_API` has no field by design — it is a CI/debug switch, not a user option.
 */
export type FigmaOptions = FigmaViewportOptions & {
    mode?: FigmaMode;
    accessToken?: string;
    maxRateLimitWaitSeconds?: number;
    nodesCacheTtlSeconds?: number;
    tempPath?: string;
};
export type FigmaNodeRef = {
    fileId: string;
    nodeId: string;
};
export type FigmaNodeMetadata = {
    name: string;
    type: string;
    width: number;
    height: number;
    revision: string;
    lastModifiedAt: string;
};
export type FigmaImageResult = {
    imagePath: string;
    metadata: FigmaNodeMetadata;
};
export type FigmaViewport = {
    width: number;
    height: number;
};
export type FigmaViewportOptions = {
    maxViewportHeight?: number;
    /**
     * One dimension, not a width/height pair: the same floor applies to both axes independently, so 320
     * means "at least 320 wide AND at least 320 tall". `null` disables the floor.
     */
    minViewportSize?: number | null;
};
export type FigmaBaselineLink = {
    figmaEnvName: string;
    useLatestEnvBaseline: boolean;
};
/** The throwaway Figma-reference test's config: a subset of core `OpenSettings` plus `saveNewTests` (maps to close's `updateBaselineIfNew`). */
export type FigmaReferenceConfig = Partial<OpenSettings> & {
    saveNewTests?: boolean;
};
export type FigmaBaselineDeps = {
    fetchFigmaImages: (figmaUrls: string[]) => Promise<FigmaImageResult[]>;
    fetchFigmaMetadata: (figmaUrls: string[]) => Promise<FigmaNodeMetadata[]>;
    createPlaceholderImage: (width: number, height: number) => Promise<string>;
    padDesignImage: (imagePath: string, width: number, height: number, minViewportSize: number) => Promise<{
        imagePath: string;
        width: number;
        height: number;
    }>;
    runFigmaCheck: (config: FigmaReferenceConfig, checks: Array<{
        imagePath: string;
        tag: string;
    }>) => Promise<{
        isNew: boolean;
        diffs: boolean;
    }>;
};
